const token = global.get("vivacrm_access_token");
const participant = msg.payload;

msg.participant = participant;
const clientId = participant?.client?.id;
if (!clientId) {
  msg.payload = participant;
  return msg;
}

msg.method = "GET";
msg.url = `https://api.vivacrm.ru/api/v1/clients/${clientId}`;
msg.headers = { Authorization: `Bearer ${token}` };
return msg;

const LK_FIELD_ID = "f9790818-25fd-4b73-a781-79c02720727d";   // Уровень Падел ЛК
const NUM_FIELD_ID = "eabfe27b-3f72-4496-9185-1a2ec6e6465e";  // Уровень падел числовой

const client = msg.payload;
const participant = msg.participant;

const getField = (id) => client?.customFields?.find((f) => f.id === id)?.value?.[0];

const letter = getField(LK_FIELD_ID);
const numericRaw = getField(NUM_FIELD_ID);

const toFixed5 = (v) => {
  if (v == null) return null;
  const n = Number(String(v).replace(",", "."));
  return Number.isFinite(n) ? n.toFixed(5) : null;
};

const numeric = toFixed5(numericRaw);

let rating = null;
let ratingSource = "phone";

if (numeric) {
  rating = numeric;
  ratingSource = "numeric";
} else if (letter) {
  rating = letter;
  ratingSource = "letter";
} else if (participant?.client?.phone) {
  rating = participant.client.phone;
  ratingSource = "phone";
}

msg.payload = {
  ...participant,
  rating,
  ratingSource
};
return msg;

const body = msg.payload || {};
const now = new Date().toISOString();

const params = body.params || {
  K: 0.3,
  D: 3,
  B: 0.3,
  Influence: 0.5,
  weights: { verif: 0.5, regularity: 0.3, engagement: 0.2 },
  minRating: 1,
  maxRating: 7,
  round: 5,
};

msg.query = { tournamentId: body.tournamentId };

msg.payload = {
  $set: {
    tournamentId: body.tournamentId,
    tenantKey: body.tenantKey || null,
    updatedAt: now,
    tournamentType: body.tournamentType || "americano",
    targetScore: body.targetScore ?? 21,
    courts: body.courts || [],
    organizer: body.organizer || {},
    participants: body.participants || [],
    rounds: body.rounds || [],
    params,
    playerLogs: body.playerLogs || {},
    totals: body.totals || {}
  },
  $setOnInsert: { createdAt: body.createdAt || now }
};

return msg;

const filter = msg.query || msg.mongoQuery || (Array.isArray(msg.payload) ? (msg.payload[0] || {}) : {}) || {};
const update = Array.isArray(msg.payload) ? (msg.payload[1] || {}) : (msg.payload || {});
const setDoc = update && typeof update === "object" && update.$set && typeof update.$set === "object" ? update.$set : null;
const setOnInsertDoc = update && typeof update === "object" && update.$setOnInsert && typeof update.$setOnInsert === "object" ? update.$setOnInsert : null;
if (setDoc && setOnInsertDoc) {
  for (const key of Object.keys(setOnInsertDoc)) {
    if (Object.prototype.hasOwnProperty.call(setDoc, key)) {
      delete setDoc[key];
    }
  }
}
msg.payload = [filter, update, { upsert: true }];
delete msg.query;
delete msg.mongoQuery;
delete msg.mongoUpdate;
return msg;

const roundTo = (n, d) => Number(n.toFixed(d));
const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
const toNum = (v, f = 0) => (Number.isFinite(Number(v)) ? Number(v) : f);

const tournament = msg.payload;
if (!tournament) {
  msg.statusCode = 404;
  msg.payload = { error: "Tournament not found" };
  return msg;
}

const body = msg.req?.body || {};
const results = Array.isArray(body.results) ? body.results : [];
const now = new Date().toISOString();

const params = Object.assign({}, tournament.params || {}, body.params || {});
const K = toNum(params.K, 0.3);
const D = toNum(params.D, 3);
const B = toNum(params.B, 0.3);
const Influence = toNum(params.Influence, 0.5);
const Wv = toNum(params.weights?.verif, 0.5);
const Wr = toNum(params.weights?.regularity, 0.3);
const We = toNum(params.weights?.engagement, 0.2);
const MIN_R = toNum(params.minRating, 1);
const MAX_R = toNum(params.maxRating, 7);
const ROUND = toNum(params.round, 5);

// --- ensure rounds/matches exist even for old tournaments ---
if (!Array.isArray(tournament.rounds)) tournament.rounds = [];

const roundIndexFromId = (id) => {
  const m = String(id || "").match(/round-(\d+)/i);
  return m ? Number(m[1]) : tournament.rounds.length + 1;
};

const ensureRound = (roundId) => {
  let round = tournament.rounds.find((r) => r.id === roundId);
  if (!round) {
    round = { id: roundId, index: roundIndexFromId(roundId), matches: [] };
    tournament.rounds.push(round);
  }
  if (!Array.isArray(round.matches)) round.matches = [];
  return round;
};

const ensureMatch = (round, matchId) => {
  let match = round.matches.find((m) => m.id === matchId);
  if (!match) {
    match = { id: matchId, court: null, pair1: [], pair2: [], score1: null, score2: null };
    round.matches.push(match);
  }
  return match;
};

// patch scores into rounds (create if missing)
results.forEach((r) => {
  if (!r?.roundId || !r?.matchId) return;
  const round = ensureRound(r.roundId);
  const match = ensureMatch(round, r.matchId);

  if (Array.isArray(r.pair1) && r.pair1.length) match.pair1 = r.pair1;
  if (Array.isArray(r.pair2) && r.pair2.length) match.pair2 = r.pair2;
  if (r.court) match.court = r.court;
  if (r.score1 !== undefined) match.score1 = r.score1;
  if (r.score2 !== undefined) match.score2 = r.score2;
});

// --- build players map ---
const players = {};
(tournament.participants || []).forEach((p, idx) => {
  const id = p.id || p.phone || `p-${idx}`;
  players[id] = {
    id,
    name: p.name || `Участник ${idx + 1}`,
    rating: toNum(p.rating, MIN_R),
    baseRating: toNum(p.rating, MIN_R),
    verif: toNum(p.verif, 0.1),
    regularity: toNum(p.regularity, 1),
    engagement: toNum(p.engagement, 1),
    pressure: toNum(p.pressure, 1),
    tournamentMultiplier: toNum(p.tournamentMultiplier, 1),
    delta: 0,
    stats: { wins: 0, losses: 0, draws: 0, games: 0, pointsFor: 0, pointsAgainst: 0 },
  };
});

const pairRating = (a, b) => (a.rating * a.rating + b.rating * b.rating) / (a.rating + b.rating);

const calcDelta = (player, oppPairRating, actual, verifOpp) => {
  const expected = 1 / (1 + Math.pow(10, (oppPairRating - player.rating) / D));
  const base = K * (actual - expected);
  const Cself = Wv * player.verif + Wr * player.regularity + We * player.engagement;
  const CselfApplied = (1 - Influence) + Influence * Cself;
  const Copp = (1 - Influence) + Influence * verifOpp;
  const delta = base * CselfApplied * Copp * player.pressure * player.tournamentMultiplier;
  return { delta: roundTo(delta, ROUND), expected };
};

// rebuild logs from scratch
const playerLogs = {};

const addLog = (playerId, log) => {
  if (!playerLogs[playerId]) playerLogs[playerId] = [];
  playerLogs[playerId].push(log);
};

tournament.rounds.forEach((round) => {
  (round.matches || []).forEach((match) => {
    if (!match || !Array.isArray(match.pair1) || !Array.isArray(match.pair2)) return;
    if (match.pair1.length < 2 || match.pair2.length < 2) return;
    if (match.score1 == null || match.score2 == null) return;

    const p1a = players[match.pair1[0]];
    const p1b = players[match.pair1[1]];
    const p2a = players[match.pair2[0]];
    const p2b = players[match.pair2[1]];
    if (!p1a || !p1b || !p2a || !p2b) return;

    const score1 = toNum(match.score1, 0);
    const score2 = toNum(match.score2, 0);

    const S1 = 1 / (1 + Math.exp(-B * (score1 - score2)));
    const S2 = 1 / (1 + Math.exp(-B * (score2 - score1)));

    const verifOpp1 = (p2a.verif + p2b.verif) / 2;
    const verifOpp2 = (p1a.verif + p1b.verif) / 2;

    const Rpair1 = pairRating(p1a, p1b);
    const Rpair2 = pairRating(p2a, p2b);

    const r11 = calcDelta(p1a, Rpair2, S1, verifOpp1);
    const r12 = calcDelta(p1b, Rpair2, S1, verifOpp1);
    const r21 = calcDelta(p2a, Rpair1, S2, verifOpp2);
    const r22 = calcDelta(p2b, Rpair1, S2, verifOpp2);

    const res1 = score1 > score2 ? "win" : score1 < score2 ? "loss" : "draw";
    const res2 = score2 > score1 ? "win" : score2 < score1 ? "loss" : "draw";

    const apply = (p, d) => {
      const before = p.rating;
      p.delta += d;
      p.rating = roundTo(clamp(p.rating + d, MIN_R, MAX_R), ROUND);
      return { before, after: p.rating };
    };

    [p1a, p1b].forEach((p) => {
      p.stats.games += 1;
      p.stats.pointsFor += score1;
      p.stats.pointsAgainst += score2;
      if (res1 === "win") p.stats.wins += 1;
      else if (res1 === "loss") p.stats.losses += 1;
      else p.stats.draws += 1;
    });

    [p2a, p2b].forEach((p) => {
      p.stats.games += 1;
      p.stats.pointsFor += score2;
      p.stats.pointsAgainst += score1;
      if (res2 === "win") p.stats.wins += 1;
      else if (res2 === "loss") p.stats.losses += 1;
      else p.stats.draws += 1;
    });

    const a11 = apply(p1a, r11.delta);
    const a12 = apply(p1b, r12.delta);
    const a21 = apply(p2a, r21.delta);
    const a22 = apply(p2b, r22.delta);

    match.results = match.results || {};
    match.results[p1a.id] = { actual: S1, ratingBefore: a11.before, ratingAfter: a11.after, delta: r11.delta };
    match.results[p1b.id] = { actual: S1, ratingBefore: a12.before, ratingAfter: a12.after, delta: r12.delta };
    match.results[p2a.id] = { actual: S2, ratingBefore: a21.before, ratingAfter: a21.after, delta: r21.delta };
    match.results[p2b.id] = { actual: S2, ratingBefore: a22.before, ratingAfter: a22.after, delta: r22.delta };

    addLog(p1a.id, { roundId: round.id, matchId: match.id, scoreFor: score1, scoreAgainst: score2, delta: r11.delta, ratingBefore: a11.before, ratingAfter: a11.after, expected: r11.expected, actual: S1 });
    addLog(p1b.id, { roundId: round.id, matchId: match.id, scoreFor: score1, scoreAgainst: score2, delta: r12.delta, ratingBefore: a12.before, ratingAfter: a12.after, expected: r12.expected, actual: S1 });
    addLog(p2a.id, { roundId: round.id, matchId: match.id, scoreFor: score2, scoreAgainst: score1, delta: r21.delta, ratingBefore: a21.before, ratingAfter: a21.after, expected: r21.expected, actual: S2 });
    addLog(p2b.id, { roundId: round.id, matchId: match.id, scoreFor: score2, scoreAgainst: score1, delta: r22.delta, ratingBefore: a22.before, ratingAfter: a22.after, expected: r22.expected, actual: S2 });
  });
});

const totals = {};
Object.values(players).forEach((p) => {
  totals[p.id] = {
    ratingBefore: roundTo(p.baseRating, ROUND),
    ratingAfter: roundTo(p.rating, ROUND),
    deltaTotal: roundTo(p.delta, ROUND),
    wins: p.stats.wins,
    losses: p.stats.losses,
    draws: p.stats.draws,
    pointsFor: p.stats.pointsFor,
    pointsAgainst: p.stats.pointsAgainst,
  };
});

tournament.playerLogs = playerLogs;
tournament.totals = totals;
tournament.updatedAt = now;

msg.mongoQuery = { tournamentId: tournament.tournamentId };
msg.mongoUpdate = { $set: { rounds: tournament.rounds, totals, playerLogs, updatedAt: now } };

msg.payload = {
  tournamentId: tournament.tournamentId,
  rounds: tournament.rounds,
  totals,
  playerLogs,
};

return msg;

const filter = msg.query || msg.mongoQuery || (Array.isArray(msg.payload) ? (msg.payload[0] || {}) : {}) || {};
const update = Array.isArray(msg.payload) ? (msg.payload[1] || {}) : (msg.payload || {});
const setDoc = update && typeof update === "object" && update.$set && typeof update.$set === "object" ? update.$set : null;
const setOnInsertDoc = update && typeof update === "object" && update.$setOnInsert && typeof update.$setOnInsert === "object" ? update.$setOnInsert : null;
if (setDoc && setOnInsertDoc) {
  for (const key of Object.keys(setOnInsertDoc)) {
    if (Object.prototype.hasOwnProperty.call(setDoc, key)) {
      delete setDoc[key];
    }
  }
}
msg.payload = [filter, update, { upsert: false }];
delete msg.query;
delete msg.mongoQuery;
delete msg.mongoUpdate;
return msg;

const t = msg.payload;
if (!t) {
  msg.statusCode = 404;
  msg.payload = { error: "Tournament not found" };
  return msg;
}

const format = String(msg.req?.query?.format || "csv").toLowerCase();
const nameById = {};
(t.participants || []).forEach(p => { nameById[p.id] = p.name; });

const rows = [];
const logs = t.playerLogs || {};
Object.keys(logs).forEach(pid => {
  (logs[pid] || []).forEach(entry => {
    rows.push({
      playerId: pid,
      playerName: nameById[pid] || "",
      roundId: entry.roundId,
      matchId: entry.matchId,
      scoreFor: entry.scoreFor,
      scoreAgainst: entry.scoreAgainst,
      delta: entry.delta,
      ratingBefore: entry.ratingBefore,
      ratingAfter: entry.ratingAfter,
      expected: entry.expected,
      actual: entry.actual
    });
  });
});

if (format === "xlsx") {
  const XLSX = global.get('XLSX');
  if (!XLSX) {
    msg.statusCode = 501;
    msg.payload = { error: "XLSX module not installed. Use format=csv or install xlsx" };
    return msg;
  }
  const ws = XLSX.utils.json_to_sheet(rows);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "history");
  const buffer = XLSX.write(wb, { type: "buffer", bookType: "xlsx" });
  msg.headers = {
    "Content-Type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    "Content-Disposition": "attachment; filename=americano-history.xlsx"
  };
  msg.payload = buffer;
  return msg;
}

// CSV fallback
const escapeCsv = (v) => {
  const s = String(v ?? "");
  if (s.includes(',') || s.includes('"') || s.includes('\n')) {
    return '"' + s.replace(/"/g, '""') + '"';
  }
  return s;
};

const header = Object.keys(rows[0] || { playerId:"", playerName:"", roundId:"", matchId:"", scoreFor:"", scoreAgainst:"", delta:"", ratingBefore:"", ratingAfter:"", expected:"", actual:"" });
const csv = [header.join(',')].concat(rows.map(r => header.map(k => escapeCsv(r[k])).join(','))).join('\n');

msg.headers = {
  "Content-Type": "text/csv; charset=utf-8",
